import{_ as l,l as i,o as a,c as s,v as e,p as n,x as t,d as m,i as d,S as u}from"./chunks/framework.InCnrqk-.js";const O=JSON.parse('{"title":"OLMo 2","description":"","frontmatter":{"title":"OLMo 2","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/olmo2.md","filePath":"llm/olmo2.md","lastUpdated":1789023840000}'),c={name:"llm/olmo2.md"};function p(h,o,B,L,A,M){const r=i("Mermaid");return a(),s("div",null,[o[1]||(o[1]=e('<h1 id="olmo-2" tabindex="-1">OLMo 2 <a class="header-anchor" href="#olmo-2" aria-label="Permalink to &quot;OLMo 2&quot;">​</a></h1><div class="epigraph"><p>OLMo 2 要交付的不只是一份能打的稠密权重，而是数据、代码、日志与中间检查点一起公开——把「开放」从开权重推进到可复现的训练配方。</p><footer>—— OLMo Team，*2 OLMo 2 Furious*，arXiv:2501.00656</footer></div><p>Allen Institute for AI（Ai2）的第一代 OLMo 已经把预训练数据与代码摊开。OLMo 2 在 2024 年底到 2025 年初给出下一代稠密解码器：<strong>7B、13B，以及随后的 32B</strong>，并在标题戏仿的技术报告 <em>2 OLMo 2 Furious</em> 里把稳定性改动、两阶段预训练和 <a href="/llm/tulu">Tulu 3</a> 式后训练写成可核对表。与只开权重的 Llama / Qwen 对照，它的主张是：在更少的训练 FLOPs 上走到同类英语学业基准的 Pareto 前沿，同时让外部研究者能重放数据混合与损失尖峰。本篇按该报告写，不把 <a href="/llm/olmoe">OLMoE</a> 的稀疏路由安到稠密 2 代上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开权重模型可以刷榜，却回答不了「这一分是数据、是归一化，还是某次损失爆炸之后的侥幸」。研究记忆、概念习得、课程学习，需要逐步检查点与可审计语料。OLMo-0424 已经用数据混合补过 MMLU；OLMo 2 要补的是另一块：<strong>更深、更长的训练如何在不发散的前提下把每 token 效率抬上去</strong>，以及退火阶段能否用专门混合（Dolmino Mix）补能力，而不是把全部 5T–6T 都当成同一锅汤。</p><p>第二个问题是后训练是否接得上。若底座只在学业多选上好看、Tulu 配方一微调就塌，开放底座的产品价值仍低。报告因此把 Instruct 当成交付物：许可友好的 SFT / DPO，再加可验证奖励的强化学习（RLVR）。</p><h3 id="稳定性比再堆一层-swiglu-更先" tabindex="-1">稳定性比再堆一层 SwiGLU 更先 <a class="header-anchor" href="#稳定性比再堆一层-swiglu-更先" aria-label="Permalink to &quot;稳定性比再堆一层 SwiGLU 更先&quot;">​</a></h3><p>相对 OLMo 1 / 0424，2 代改的是归一化位置与数值护栏，不是激活函数：仍无 bias、仍 <a href="/llm/swiglu">SwiGLU</a>、仍 RoPE。变化包括：RMSNorm 替代非参数 LayerNorm；<strong>归一化改打在注意力与 MLP 的输出上</strong>（重排的 post-norm）；查询与键在算点积前做 RMSNorm（QK-Norm）；最终 logits 加权重 \\(10^{-5}\\) 的 Z-loss；RoPE \\(\\theta\\) 从 \\(10^4\\) 提到 \\(5\\times 10^5\\)；嵌入不做 weight decay。0424 曾用把 QKV 裁到 8 来压抑 logits，2 代改成 QK-Norm，避免注意力分数爆炸导致的损失发散。</p><p><span class="marginnote">7B 与 13B 仍是多头注意力；32B 才改 <a href="/llm/gqa">GQA</a>（40 个查询头 / 8 个 KV 头）。不要把三档都写成 GQA，也不要把 32B 的日期后缀 0325 与 7B/13B 的 1124 混成同一次预训练。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>稠密解码器，序列长度 4096。报告中的形状：7B 为 32 层、\\(d=4096\\)、32/32 头；13B 为 40 层、\\(d=5120\\)、40/40 头；32B 为 64 层、\\(d=5120\\)、40/8 GQA。预训练数据 <code>olmo-mix-1124</code>，中训 / 退火数据 <code>dolmino-mix-1124</code>。7B/13B 的余弦日程按约 <strong>5T token</strong> 量级写；家族叙述为最多约 6T。Dolmino 不在第一步就混入，而是在后期课程里打补丁：用小规模 micro-annealing 先评估数据源，再决定是否进入正式退火，降低「为试一种数学混合而重跑 5T」的成本。</p><h3 id="从底座到-instruct" tabindex="-1">从底座到 Instruct <a class="header-anchor" href="#从底座到-instruct" aria-label="Permalink to &quot;从底座到 Instruct&quot;">​</a></h3><p>后训练跟 Tulu 3：SFT → DPO → <strong>RLVR</strong>（可验证奖励，用于数学等能自动判对的任务）。数据强调可许可来源。检查点、训练日志、数千中间权重与 <a href="/llm/dolma-fineweb">Dolma</a> 系工具链一并公开，评估走 OLMES 套件，避免「同一 MMLU、三种不同 shot 设定」。API 名称以 Hugging Face 上 <code>OLMo-2-1124-*</code> 与 <code>OLMo-2-0325-32B</code> 为准。</p>',13)),(a(),n(u,null,{default:t(()=>[d(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20MIX%5B%22olmo-mix-1124%20%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%20--%3E%20STAB%5B%22RMSNorm%20%E8%BE%93%E5%87%BA%E4%BE%A7%20%2B%20QK-Norm%20%2B%20Z-loss%22%5D%0A%20%20STAB%20--%3E%20BASE%5B%22OLMo%202%20Base%207B%20%2F%2013B%20%2F%2032B%22%5D%0A%20%20DOL%5B%22dolmino-mix-1124%20%E9%80%80%E7%81%AB%22%5D%20--%3E%20BASE%0A%20%20BASE%20--%3E%20SFT%5B%22Tulu%203%20%E5%BC%8F%20SFT%22%5D%0A%20%20SFT%20--%3E%20DPO%5B%22DPO%22%5D%0A%20%20DPO%20--%3E%20RLVR%5B%22RLVR%20%E5%8F%AF%E9%AA%8C%E8%AF%81%E5%A5%96%E5%8A%B1%22%5D%0A%20%20RLVR%20--%3E%20INS%5B%22OLMo%202%20Instruct%22%5D%0A"})]),fallback:t(()=>[...o[0]||(o[0]=[m(" Loading... ",-1)])]),_:1})),o[2]||(o[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>QK-Norm 把 \\(q,k\\) 的尺度钉住，点积方差不再随层深漂到 softmax 饱和区——与 <a href="/llm/sdpa">SDPA</a> 里 \\(1/\\sqrt{d_k}\\) 是同一类「别让 logits 炸」，只是多了一层可学习（或 RMS）的护栏。输出侧 RMSNorm 改变残差流上的尺度积累：入口不再预归一化时，梯度路径不同，报告用消融说明<strong>单独改 post-norm 或单独 QK-Norm 都不够，合在一起才压住梯度范数的尖峰</strong>。Z-loss 惩罚过大的最终 logits，减少半精度下的溢出与训练后期的数值噪声。</p><p>Dolmino 的机制是课程而不是神秘新数据：预训练把通用网页与代码铺开，退火提高数学、指令风格、高质量回放的密度。micro-annealing 把「这一锅值不值得」从完整重训里拆出来。Instruct 上，RLVR 只在有 checker 的任务上给奖励，避免纯偏好模型在格式上钻空子；它补的是底座已经具备、但格式不稳定的解题能力，而不是从零教算术。</p><p><span class="marginnote">「完全开放」仍受单份数据许可证的约束：混合里若含 CC-BY-NC 或特定来源条款，下游商用要按成分读，而不能因模型权重 Apache 2.0 就假设语料可任意再分发。报告自己的表述是能 Apache 则 Apache，否则取最宽松的可用许可。</span></p><h3 id="和-olmoe、只开权重模型的差别" tabindex="-1">和 OLMoE、只开权重模型的差别 <a class="header-anchor" href="#和-olmoe、只开权重模型的差别" aria-label="Permalink to &quot;和 OLMoE、只开权重模型的差别&quot;">​</a></h3><p>OLMoE 用 64 专家 top-8 在约 1B 激活上做稀疏对照；OLMo 2 是稠密容量与稳定性实验。两者共享 Ai2 的开放哲学，不共享 FFN 形状。相对 Llama 3.1 / Qwen 2.5，OLMo 2 的对照句是「更少 FLOPs、可审计数据」，不是「秘密数据量更大」。读图要用报告的 Pareto 图与 Table，不要口头升级成全面超过 405B。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>上下文默认 4K，不是 128K 叙事；RoPE \\(\\theta\\) 加到 \\(5\\times 10^5\\) 是为训练长度与外推留余量，不等于已经按 128K 训过。32B 的 GQA 与 7B 的 MHA 在推理栈上 KV 布局不同，不能同一套缓存配置硬套。评测以 OLMES 与报告表为准；第三方 Arena 分数不是论文主表。</p><p>不要把 OLMo 2 写成视觉或 MoE。不要给 Dolmino 编造单独的 arXiv。Instruct 的 RLVR 依赖可验证任务，开放聊天上的安全与拒答仍要另做系统层，底座开放不等于对齐完成。</p><p>训练栈本身被报告写成研究条件：从 OLMo-0424 到 2 代换了监控与编排，降低失败率、提高集群利用率。这对外部复现的含义是：公开配方仍假设你有稳定的多机通信与检查点磁盘；把 13B 塞进单卡实验，只能验证损失曲线的局部，不能验证他们写的尖峰统计。中间检查点的价值在于画「能力何时出现」，不在于每一个都能当生产 Instruct。选服务权重用最终 Base / Instruct，分析用逐步存档，两套不要混。</p><p><span class="marginnote">第一代 OLMo 的出处是 Groeneveld 等 2024；0424 是 Ai2 博客迭代。引用 2 代时用 <em>2 OLMo 2 Furious</em>，arXiv:2501.00656。标题是双关，不是第二篇叫 Furious 的独立论文。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OLMo 2 是 Ai2 的全开放稠密模型：7B / 13B / 32B，数据、代码、中间检查点一起发。</li><li>稳定性来自输出侧 RMSNorm、QK-Norm、Z-loss 与更高 RoPE \\(\\theta\\)，而不是新的注意力核。</li><li>预训练 olmo-mix-1124，退火 dolmino-mix-1124；Instruct 走 Tulu 3 + RLVR。</li><li>7B/13B 为 MHA，32B 为 GQA；默认训练长度 4K。</li><li>出处：OLMo Team，<em>2 OLMo 2 Furious</em>，arXiv:2501.00656，2024/2025。</li></ul>',13))])}const T=l(c,[["render",p]]);export{O as __pageData,T as default};
